from collections import deque
mask=np.zeros_like(A,dtype=bool)
# source components only left c0:12
mask[:,:12] = A[:,:12] != 3
seen=set(); comps=[]
for r in range(A.shape[0]):
  for c in range(12):
    if not mask[r,c] or (r,c) in seen: continue
    q=[(r,c)]; seen.add((r,c)); comp=[]
    while q:
      x,y=q.pop(); comp.append((x,y))
      for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
        nx,ny=x+dx,y+dy
        if 0<=nx<20 and 0<=ny<12 and mask[nx,ny] and (nx,ny) not in seen:
          seen.add((nx,ny)); q.append((nx,ny))
    comps.append(comp)
for i,co in enumerate(sorted(comps,key=lambda x:min(x))):
  r0=min(r for r,c in co);r1=max(r for r,c in co);c0=min(c for r,c in co);c1=max(c for r,c in co)
  print(i, 'n',len(co),'bbox',(r0,r1+1,c0,c1+1))
  for rr in range(r0,r1+1):
    print(' ', ''.join('.' if (rr,cc) not in co else str(A[rr,cc]) for cc in range(c0,c1+1)))

target=A[:,12:] == 3
print('target rows local c0..7:')
for r in range(20): print(f'{r:02}', ''.join('#' if x else '.' for x in target[r]))

# Build normalized source pieces and placements into target mask.
pieces=[]
for comp in comps:
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    cells=tuple(sorted((r-r0,c-c0,int(A[r,c])) for r,c in comp))
    h=max(r for r,c in comp)-r0+1; w=max(c for r,c in comp)-c0+1
    pieces.append({'cells':cells,'h':h,'w':w,'id':len(pieces)})
# row-major indexing for panel target cells, but bit positions across the 160 panel cells.
cellbit={(r,c):1 << (r*8+c) for r in range(20) for c in range(8) if target[r,c]}
cellcoords=list(cellbit)
placements=[]
bycell={cell:[] for cell in cellcoords}
for pi,piece in enumerate(pieces):
    for r0 in range(20-piece['h']+1):
        for c0 in range(8-piece['w']+1):
            pos=[]; ok=True
            for dr,dc,val in piece['cells']:
                q=(r0+dr,c0+dc)
                if not target[q]:
                    ok=False; break
                pos.append((q,val))
            if not ok: continue
            bm=sum(cellbit[q] for q,val in pos)
            pidx=len(placements)
            pl={'piece':pi,'origin':(r0,c0),'pos':tuple(pos),'mask':bm,'idx':pidx}
            placements.append(pl)
            for q,val in pos: bycell[q].append(pl)
print('pieces',len(pieces),'placements',len(placements),'candidate count range per cell',min(map(len,bycell.values())),max(map(len,bycell.values())))
for i,p in enumerate(pieces): print(i,(p['h'],p['w']),p['cells'],sum(pl['piece']==i for pl in placements))
